sys_script_include.script:
var Cisco_Secure_Access_Private_Resource_Groups = Class.create();
Cisco_Secure_Access_Private_Resource_Groups.prototype = {
	initialize: function () {
	},

	fetchAndInsertPrivateResourceGroups: function () {
		try {
			gs.info("[Cisco Secure Access - PRG] === Script Started ===");

			// 1. Load existing SNOW records into a map by name
			var snowRecords = {};
			var grSnow = new GlideRecord("u_cisco_secure_access_private_resources_group");
			grSnow.query();
			while (grSnow.next()) {
				var name = grSnow.getValue("u_name");
				if (name) {
					snowRecords[name] = {
						sys_id: grSnow.getUniqueValue(),
						description: grSnow.getValue("u_description"),
						resource_ids: grSnow.getValue("u_resource_ids"),
						created_by: grSnow.getValue("u_created_by"),
						modified_by: grSnow.getValue("u_modified_by"),
						created_at: grSnow.getValue("u_created_at"),
						modified_at: grSnow.getValue("u_modified_at"),
						resource_group_id: grSnow.getValue("u_resource_group_id")
					};
				}
			}
			gs.info("[Cisco Secure Access - PRG] Existing SNOW records loaded: " + Object.keys(snowRecords).length);

			// 2. Fetch all Cisco Secure Access resource groups
			var token = new CiscoSecureAccessGetToken().getLatestAccessToken();
			var r = new sn_ws.RESTMessageV2("Cisco Secure Access Private Res Groups", "GET Private Resource Groups");
			r.setRequestHeader("Authorization", "Bearer " + token);
			r.setRequestHeader("Accept", "application/json");
			var response = r.execute();
			var status = response.getStatusCode();
			var body = response.getBody();

			if (status !== 200) {
				gs.error("[Cisco Secure Access - PRG] Cisco Secure Access API Error: " + status + " - " + body);
				return;
			}

			var parsed = JSON.parse(body);
			var csaItems = parsed.items || [];
			gs.info("[Cisco Secure Access - PRG] Cisco Secure Access resource groups fetched: " + csaItems.length);

			var updatedCount = 0;
			var skippedCount = 0;

			for (var i = 0; i < csaItems.length; i++) {
				var item = csaItems[i];
				var name = item.name;

				// Only update existing records
				if (snowRecords[name]) {
					var existing = snowRecords[name];
					var grUpdate = new GlideRecord("u_cisco_secure_access_private_resources_group");
					if (grUpdate.get(existing.sys_id)) {
						var needUpdate = false;
						var updateFields = [];

						if (!existing.description && item.description) {
							grUpdate.setValue("u_description", item.description);
							updateFields.push("u_description");
							needUpdate = true;
						}
						if (!existing.resource_ids && item.resourceIds) {
							grUpdate.setValue("u_resource_ids", item.resourceIds.join(","));
							updateFields.push("u_resource_ids");
							needUpdate = true;
						}
						if (!existing.created_by && item.createdBy) {
							grUpdate.setValue("u_created_by", item.createdBy);
							updateFields.push("u_created_by");
							needUpdate = true;
						}
						if (!existing.modified_by && item.modifiedBy) {
							grUpdate.setValue("u_modified_by", item.modifiedBy);
							updateFields.push("u_modified_by");
							needUpdate = true;
						}
						if (!existing.created_at && item.createdAt) {
							grUpdate.setValue("u_created_at", item.createdAt);
							updateFields.push("u_created_at");
							needUpdate = true;
						}
						if (!existing.modified_at && item.modifiedAt) {
							grUpdate.setValue("u_modified_at", item.modifiedAt);
							updateFields.push("u_modified_at");
							needUpdate = true;
						}
						if (!existing.resource_group_id && item.resourceGroupId) {
							grUpdate.setValue("u_resource_group_id", item.resourceGroupId);
							updateFields.push("u_resource_group_id");
							needUpdate = true;
						}

						if (needUpdate) {
							grUpdate.update();
							updatedCount++;
							gs.info("[Cisco Secure Access - PRG] Updated: " + name + " | Fields: " + updateFields.join(", "));
						} else {
							skippedCount++;
							gs.info("[Cisco Secure Access - PRG] No updates needed for: " + name);
						}
					}
				} else {
					// Skipped due to no matching SNOW record
					gs.info("[Cisco Secure Access - PRG] Skipped: Cisco Secure Access group '" + name + "' not found in SNOW.");
					skippedCount++;
				}
			}

			gs.info("[Cisco Secure Access - PRG] === Script Complete ===");
			gs.info("[Cisco Secure Access - PRG] Records updated: " + updatedCount);
			gs.info("[Cisco Secure Access - PRG] Records skipped: " + skippedCount);

		} catch (e) {
			gs.error("[Cisco Secure Access - PRG] Script Error: " + e.message);
		}
	},

	type: 'Cisco_Secure_Access_Private_Resource_Groups'
};
